from lib import *
import sympy as sp
LESSON = 'កន្សោមពីជគណិត'
x, y, a, b, c, m, n, z = sp.symbols('x y a b c m n z')
def L(e): return sp.latex(e, order='lex', mul_symbol=None)
def E(e): return M(L(e))
def W(ans, cand, k=3):
    out = []
    for c_ in cand:
        c_ = sp.expand(c_)
        if sp.simplify(c_ - ans) != 0 and all(sp.simplify(c_ - o) != 0 for o in out): out.append(c_)
    t = 1
    while len(out) < k:
        c_ = sp.expand(ans + t * (1 if t % 2 else -1)); t += 1
        if all(sp.simplify(c_ - o) != 0 for o in out) and sp.simplify(c_ - ans) != 0: out.append(c_)
    return [E(o) for o in out[:k]]
def ev(expr, sub): return sp.simplify(expr.subs(sub))

