    C.append(wr('pisa', 'pisa', 'លោកលីទិញទឹកក្រូច ' + M(2) + ' កេសថ្លៃមួយកេស ' + M('x') + ' ម៉ឺនរៀល និងទឹកផ្លែឈើ ' + M(5) + ' កេសថ្លៃមួយកេស ' + M('y') + ' ម៉ឺនរៀល។ ក. សរសេរថ្លៃសរុបជាកន្សោម។ ខ. គណនាពេល ' + M('x = 6, y = 4') + '។ គ. ប្រៀបធៀបថ្លៃពេល ' + M('x = 5, y = 5') + '។', [('ក. ' + M('2x + 5y'), 1), ('ខ. ' + M('2(6) + 5(4) = 12 + 20 = 32') + ' ម៉ឺនរៀល', 2), ('គ. ' + M('2(5) + 5(5) = 35') + ' ម៉ឺនរៀល ' + M('> 32'), 2)]))
    C.append(wr('pisa', 'pisa', 'ការេមួយមានជ្រុង ' + M('x\\ \\text{cm}') + '។ គេបង្កើតចតុកោណកែងថ្មីដោយបន្ថែមទទឹង ' + M('3\\ \\text{cm}') + ' និងបណ្តោយ ' + M('5\\ \\text{cm}') + '។ ក. សរសេរផ្ទៃក្រឡាថ្មី។ ខ. គណនាពេល ' + M('x = 4') + '។ គ. ផ្ទៃក្រឡាកើនប៉ុន្មាន?', [('ក. ' + M('(x+3)(x+5) = x^2 + 8x + 15'), 2), ('ខ. ' + M('16 + 32 + 15 = 63\\ \\text{cm}^2'), 1), ('គ. ផ្ទៃក្រឡាដើម ' + M('16') + ' កើន ' + M('63 - 16 = 47\\ \\text{cm}^2'), 2)]))
    C.append(wr('pisa', 'pisa', 'ក្រុមហ៊ុនមួយយកថ្លៃសេវា ' + M('a') + ' ដុល្លារក្នុងមួយខែ បូក ' + M('b') + ' ដុល្លារក្នុងមួយម៉ោងប្រើប្រាស់។ ក. សរសេរថ្លៃក្នុង ' + M('h') + ' ម៉ោង។ ខ. បើ ' + M('a = 10, b = 3') + ' រកថ្លៃពេល ' + M('h = 6') + '។ គ. ថ្លៃមួយម៉ោងជាមធ្យមពេល ' + M('h = 6') + ' ប៉ុន្មាន?', [('ក. ' + M('a + bh'), 1), ('ខ. ' + M('10 + 3 \\times 6 = 28') + ' ដុល្លារ', 2), ('គ. ' + M('28 \\div 6 \\approx 4.67') + ' ដុល្លារក្នុងមួយម៉ោង', 2)]))
    return C
